  // ============ PART H PHASE 9: CLAN-THEMED LOOK ============
  // Recolours the sheet's own maroon/gold "brand" accent to match whichever Great Clan is
  // actually applied to the character, plus two pieces of the real ink-brush Clan mon art
  // (Art/Clan Mons/ -- the "ink only" zip variant: transparent, single-colour silhouette, no
  // AI-tool watermark, matching what the design mockup used and confirmed): a large, faint
  // watermark behind the Clan & School card's fields, and a small "colophon" centred in the
  // tab bar -- the signature-seal position on an actual scroll, visible on every tab since the
  // tab bar itself never scrolls away. See this phase's own README for the full design
  // history (three mockup rounds) and the exact source of every colour below.
  //
  // WHY THIS NEEDED NO NEW CSS FOR THE RECOLOUR ITSELF. Every button, active-tab highlight,
  // and section heading across all ten tabs already reads its colour from five CSS custom
  // properties -- --shu, --shu-dark, --shu-mid, --shu-soft, --shu-shadow -- defined once in
  // 10-sheet-base.css's own :root block (confirmed by grep: every reference in every CSS file
  // goes through var(), zero hardcoded duplicates of the literal hex values anywhere else).
  // Overriding those five custom properties on the document root, inline, wins over the
  // stylesheet's own :root declaration and re-themes everything built on them in one pass --
  // headings, active tabs, the Void pip tracker, the scroll-to-top and Quick-Access buttons,
  // all of it -- without touching a single one of those existing rules. Removing the inline
  // override falls straight back to the stylesheet's own default. That fallback IS the
  // reversibility mechanism this phase leans on hardest.
  //
  // TWO THINGS DELIBERATELY KEPT OUT OF THIS OVERRIDE. button.danger (Delete, the confirm-OK
  // button) and .wound-seg.sev-danger.current (the wound bar's most-severe segment) both also
  // read from --shu/--shu-dark today -- but those two colours are carrying real meaning
  // ("this is destructive" / "you are badly hurt"), not brand decoration. Letting a Clan's
  // colour silently soften or repaint a danger signal would be a real usability regression, so
  // 10-sheet-base.css pins both back to the sheet's own actual maroon, explicitly, regardless
  // of which Clan (if any) is themed. See the small "PART H PHASE 9" block right after those
  // two rules' original definitions.
  //
  // REVERSIBILITY -- TWO LEVELS, BOTH CHEAP. This was built with an explicit ask to stay easy
  // to back out of even after later work has landed on top of it:
  //   1. CLAN_THEME_ENABLED below is a single flag. Set it to false and rebuild: every call
  //      into this file's own functions becomes a no-op that actively clears any theming
  //      already applied, so the sheet is back to its default maroon/gold instantly, and nothing
  //      else in the codebase needs to change. The fragment and its data stay in place, ready
  //      to flip back on later.
  //   2. A full removal follows the same originals/ + ROLLBACK.md model as every other feature
  //      phase in this project -- see this phase's own ROLLBACK.md for the exact restore
  //      procedure if the flag isn't enough and the feature should be gone entirely.
  //
  // SCOPE. Only the seven Great Clans with mon art get themed (Crab, Crane, Dragon, Lion,
  // Phoenix, Scorpion, Unicorn). A character with no Clan applied yet, a Minor Clan, Spider, or
  // Imperial gets no theming at all -- the sheet keeps its default look exactly as today. (Spider
  // and Imperial have no mon art in the repo yet; Minor Clans are a separate, larger design
  // question -- which Great Clan a Minor Clan owes its colours to -- deliberately left alone
  // here rather than guessed at.)

  const CLAN_THEME_ENABLED = true;

  // Five-shade ramp per Clan, matching --shu/--shu-dark/--shu-mid/--shu-soft/--shu-shadow's own
  // HSL structure (same hue held constant, lightness stepped shadow < dark < mid < base < soft,
  // saturation ~58% dropping to ~48% for soft) -- so anything already styled against that ramp
  // keeps the same visual relationships it has today, just in a different hue. Contrast-checked
  // against the sheet's own --paper background: every "shuDark" shade (the one carrying section
  // headings and most body-text-sized accents) clears 4.5:1 -- Dragon and Lion needed an extra
  // few points of darkening beyond the others to get there; the rest cleared it unmodified.
  const CLAN_THEME_PALETTE = {
    'Crab':     { shu:'#a1622b', shuDark:'#7d4c21', shuMid:'#8d5625', shuSoft:'#c1834e', shuShadow:'#5d3819' },
    'Crane':    { shu:'#2b6ea1', shuDark:'#21557d', shuMid:'#25608d', shuSoft:'#4e8fc1', shuShadow:'#193f5d' },
    'Dragon':   { shu:'#248957', shuDark:'#1b6540', shuMid:'#1f754a', shuSoft:'#3eb178', shuShadow:'#12442b' },
    'Lion':     { shu:'#897224', shuDark:'#65531b', shuMid:'#75611f', shuSoft:'#b1973e', shuShadow:'#443912' },
    'Phoenix':  { shu:'#a1432b', shuDark:'#7d3421', shuMid:'#8d3a25', shuSoft:'#c1654e', shuShadow:'#5d2619' },
    'Scorpion': { shu:'#713d50', shuDark:'#532d3b', shuMid:'#603444', shuSoft:'#9c546e', shuShadow:'#381e28' },
    'Unicorn':  { shu:'#6a2ba1', shuDark:'#52217d', shuMid:'#5d258d', shuSoft:'#8b4ec1', shuShadow:'#3d195d' },
  };

  const CLAN_MON_DATA = {
    'Crab': "data:image/png;base64,",
    'Crane': "data:image/png;base64,",
    'Dragon': "data:image/png;base64,",
    'Lion': "data:image/png;base64,",
    'Phoenix': "data:image/png;base64,",
    'Scorpion': "data:image/png;base64,",
    'Unicorn': "data:image/png;base64,",
  };

  // getAppliedClanKey() below reads #f_clan -- the character's actual applied Clan (set by the
  // Apply Family click handler in 080-identity-build-ui.js, the same field collectData()/
  // applyData() persist) -- not #cfs_clan, the Clan & School tab's own staging dropdown, which
  // only reflects what's about to be applied. This matches how the rest of the sheet already
  // decides "what is this character," e.g. characterCasterLock() reading #f_school rather than
  // whatever #cfs_school currently shows.
  function getAppliedClanKey(){
    const el = document.getElementById('f_clan');
    const clan = (el && el.value || '').trim();
    return CLAN_THEME_PALETTE[clan] ? clan : null;
  }

  // Called from the tail of recalcAll() (see 110-modals-trackers.js) and once at boot in
  // init() -- recalcAll() already runs after every Apply Family click and after loading a
  // saved character, so this needs no narrower hook of its own the way Phase 2's Quick Access
  // panel did for Void/wound/spell-slot pips; nothing here is mutated through a path that
  // bypasses recalcAll().
  function applyClanTheme(){
    const root = document.documentElement.style;
    const watermark = document.getElementById('clanMonWatermark');
    const colophon = document.getElementById('clanMonColophon');
    const key = CLAN_THEME_ENABLED ? getAppliedClanKey() : null;

    if(!key){
      root.removeProperty('--shu');
      root.removeProperty('--shu-dark');
      root.removeProperty('--shu-mid');
      root.removeProperty('--shu-soft');
      root.removeProperty('--shu-shadow');
      root.removeProperty('--clan-mon-url');
      if(watermark) watermark.hidden = true;
      if(colophon) colophon.hidden = true;
      return;
    }

    const c = CLAN_THEME_PALETTE[key];
    root.setProperty('--shu', c.shu);
    root.setProperty('--shu-dark', c.shuDark);
    root.setProperty('--shu-mid', c.shuMid);
    root.setProperty('--shu-soft', c.shuSoft);
    root.setProperty('--shu-shadow', c.shuShadow);
    root.setProperty('--clan-mon-url', `url("${CLAN_MON_DATA[key]}")`);
    if(watermark) watermark.hidden = false;
    if(colophon) colophon.hidden = false;
  }
  // ============ END PART H PHASE 9 ============
